#: الدفترُ البسيط دفترُ إدخالٍ واحد (إيرادٌ أو مصروف) — فلا ذممَ ولا حقوقَ ملكيةٍ
#: فيه: تصنيفُ أرصدةٍ لا يُقابَل بطرفٍ ثانٍ يوهم بحسابٍ مزدوج.
SIMPLE_CODES: frozenset[str] = frozenset(
    {"1000", "1100", "1200", "4000", "4100", "5000", "5100", "5200"},
)

#: حسابُ الضريبة المستحقة — يتغيّر اسمه بالنظام الضريبي وحده، وكودُه واحد.
VAT_ACCOUNTS: dict[str, tuple[str, str, str, str]] = {
    "PS": ("2200", "ضريبة القيمة المضافة المستحقة", "2000", "liability"),
    "IL": ("2200", 'מע"מ לתשלום', "2000", "liability"),
}

TAX_SYSTEMS: tuple[str, ...] = ("PS", "IL")
BOOK_KINDS: tuple[str, ...] = ("simple", "double")


def book_account_tree(tax_system: str, book_kind: str) -> list[tuple[str, str, str, str]]:
    """شجرةُ (نظامٍ، نوع دفتر) — الدالةُ الواحدةُ التي يقرؤها الزارعُ والعاكس."""
    rows = [
        row for row in COMMON_ACCOUNTS
        if book_kind == "double" or row[0] in SIMPLE_CODES
    ]
    if book_kind == "double":
        rows.append(VAT_ACCOUNTS[tax_system])
    return sorted(rows, key=lambda row: row[0])


def seed_book_account_templates(apps, schema_editor):
    """تزرع الشجرةَ الافتراضية لكل (نظامٍ ضريبيّ، نوع دفتر) — **idempotent**.

    المفتاحُ الطبيعيّ `(tax_system, book_kind, code)` هو المدار: تشغيلُ الهجرة
    مرّتين لا يضاعف صفاً، وصفٌّ عدّله أحدٌ في القاعدة لا يُعاد كتابته.
    """
    BookAccountTemplate = apps.get_model("accounting_office", "BookAccountTemplate")
    for tax_system in TAX_SYSTEMS:
        for book_kind in BOOK_KINDS:
            for code, name, parent_code, account_type in book_account_tree(
                tax_system, book_kind,
            ):
                BookAccountTemplate.objects.get_or_create(
                    tax_system=tax_system,
                    book_kind=book_kind,
                    code=code,
                    defaults={
                        "name": name,
                        "parent_code": parent_code,
                        "account_type": account_type,
                        "is_system": True,
                    },
                )


def unseed_book_account_templates(apps, schema_editor):
    """يحذف **الصفوف التي زرعتها هذه الهجرة وحدها** — بالمفتاح الطبيعيّ نفسه."""
    BookAccountTemplate = apps.get_model("accounting_office", "BookAccountTemplate")
    for tax_system in TAX_SYSTEMS:
        for book_kind in BOOK_KINDS:
            BookAccountTemplate.objects.filter(
                tax_system=tax_system,
                book_kind=book_kind,
                code__in=[row[0] for row in book_account_tree(tax_system, book_kind)],
            ).delete()


